package com.campinggearrental.web;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.campinggearrental.model.*;
import com.campinggearrental.service.*; import com.campinggearrental.repository.RentalOrderRepository;
import com.campinggearrental.state.RentedState;
import java.math.BigDecimal; import java.sql.SQLException; import java.time.LocalDate; import java.util.List;
import org.junit.jupiter.api.*; import org.springframework.test.web.servlet.*; import org.springframework.test.web.servlet.setup.MockMvcBuilders; import org.springframework.web.servlet.view.InternalResourceViewResolver;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.test.util.ReflectionTestUtils;
class CheckoutWebControllerTest {
 private StubCheckout checkout; private MockMvc mvc; private RentalOrder order; private RentalOrderService rentalOrders; private EquipmentService equipment; private CustomerService customers;
 @BeforeEach void setUp()throws Exception{checkout=new StubCheckout();rentalOrders=mock(RentalOrderService.class);equipment=mock(EquipmentService.class);customers=mock(CustomerService.class);when(rentalOrders.findAll()).thenReturn(List.of());when(equipment.list()).thenReturn(List.of());when(customers.findAll()).thenReturn(List.of());CheckoutWebController controller=new CheckoutWebController(checkout,new PricingService(),rentalOrders,equipment,customers);ReflectionTestUtils.setField(controller,"bankName","Demo Bank");ReflectionTestUtils.setField(controller,"accountNumber","123456789");ReflectionTestUtils.setField(controller,"accountName","CAMPING GEAR RENTAL");InternalResourceViewResolver v=new InternalResourceViewResolver();v.setPrefix("classpath:/templates/");v.setSuffix(".html");mvc=MockMvcBuilders.standaloneSetup(controller).defaultRequest(get("/").session(adminSession())).setViewResolvers(v).build();order=order();}
 @Test void lookupRendersActualRentalsWithUnpaidFirst()throws Exception{RentalOrder paid=order();paid.setId("R2");paid.setPaymentStatus(PaymentStatus.PAID);when(rentalOrders.findAll()).thenReturn(List.of(paid,order));when(customers.findAll()).thenReturn(List.of(new Customer("C1","Nguyễn An","0901","", "")));mvc.perform(get("/checkout")).andExpect(status().isOk()).andExpect(view().name("checkout/lookup")).andExpect(model().attribute("rentals",List.of(order,paid))).andExpect(model().attribute("customerNames",java.util.Map.of("C1","Nguyễn An")));verify(rentalOrders).findAll();verify(customers).findAll();}
 @Test void emptyLookupRendersVietnameseEmptyState()throws Exception{mvc.perform(get("/checkout")).andExpect(status().isOk()).andExpect(model().attribute("rentals",List.of()));}
 @Test void customerSeesOnlyOwnOrders()throws Exception{RentalOrder other=order();other.setId("R2");other.setCustomerId("C2");when(rentalOrders.findAll()).thenReturn(List.of(order,other));mvc.perform(get("/checkout").session(customerSession())).andExpect(status().isOk()).andExpect(model().attribute("rentals",List.of(order)));}
 @Test void customerCannotReadAnotherCustomersCheckout()throws Exception{checkout.order=order();mvc.perform(get("/checkout/R1").session(otherCustomerSession())).andExpect(status().isForbidden());}
 @Test void customerCanSelectCashOrBankTransferAndReportTransfer()throws Exception{checkout.order=order;for(PaymentMethod method:List.of(PaymentMethod.CASH,PaymentMethod.BANK_TRANSFER)){order.setPaymentStatus(PaymentStatus.UNPAID);mvc.perform(post("/checkout/R1/payment-method").session(customerSession()).param("paymentMethod",method.name())).andExpect(redirectedUrl("/checkout/R1"));assertEquals(method,order.getPaymentMethod());}mvc.perform(post("/checkout/R1/payment-method").session(customerSession()).param("paymentMethod","VIETQR")).andExpect(redirectedUrl("/checkout/R1"));assertEquals(PaymentMethod.BANK_TRANSFER,order.getPaymentMethod());order.setPaymentStatus(PaymentStatus.UNPAID);mvc.perform(post("/checkout/R1/report-transfer").session(customerSession())).andExpect(redirectedUrl("/checkout/R1"));assertEquals(PaymentStatus.TRANSFER_REPORTED,order.getPaymentStatus());}
 @Test void customerCannotChangeOrReportAnotherCustomersPayment()throws Exception{checkout.order=order;mvc.perform(post("/checkout/R1/payment-method").session(otherCustomerSession()).param("paymentMethod","CASH")).andExpect(status().isForbidden());mvc.perform(post("/checkout/R1/report-transfer").session(otherCustomerSession())).andExpect(status().isForbidden());assertEquals(0,checkout.selections);assertEquals(0,checkout.reports);}
 @Test void customerCannotConfirmPaidEvenByCallingAdminUrl()throws Exception{checkout.order=order;mvc.perform(post("/checkout/R1/pay").session(customerSession())).andExpect(status().isForbidden());assertEquals(0,checkout.payments);assertEquals(PaymentStatus.UNPAID,order.getPaymentStatus());}
 @Test void adminCanRequestReviewOrRejectReportedTransfer()throws Exception{checkout.order=order;order.setPaymentStatus(PaymentStatus.TRANSFER_REPORTED);mvc.perform(post("/checkout/R1/payment-review")).andExpect(redirectedUrl("/checkout/R1"));assertEquals(PaymentStatus.REVIEW_REQUIRED,order.getPaymentStatus());order.setPaymentStatus(PaymentStatus.TRANSFER_REPORTED);mvc.perform(post("/checkout/R1/payment-reject")).andExpect(redirectedUrl("/checkout/R1"));assertEquals(PaymentStatus.REJECTED,order.getPaymentStatus());}
 @Test void blankLookupDoesNotCallService()throws Exception{mvc.perform(post("/checkout/load").param("rentalId"," ")).andExpect(redirectedUrl("/checkout"));assertEquals(0,checkout.loads);}
 @Test void lookupRedirectsToRentalDetailWithFeedback()throws Exception{mvc.perform(post("/checkout/load").param("rentalId"," R1 ")).andExpect(redirectedUrl("/checkout/R1")).andExpect(flash().attribute("success","Đã tải đơn thuê."));}
 @Test void detailExposesPersistedOrderAndSnapshot()throws Exception{checkout.order=order;when(equipment.list()).thenReturn(List.of(new Equipment("EQ1","Lều Alpine","CAT1",new BigDecimal("100.00"),5)));mvc.perform(get("/checkout/R1")).andExpect(status().isOk()).andExpect(view().name("checkout/detail")).andExpect(model().attribute("order",order)).andExpect(model().attribute("rentalDays",5L)).andExpect(model().attribute("equipmentNames",java.util.Map.of("EQ1","Lều Alpine")));assertEquals(1,checkout.loads);assertEquals(new BigDecimal("100.00"),order.getDetails().getFirst().getUnitPrice());verify(equipment).list();}
 @Test void missingEquipmentNameFallsBackToId()throws Exception{checkout.order=order;mvc.perform(get("/checkout/R1")).andExpect(status().isOk()).andExpect(model().attribute("equipmentNames",java.util.Map.of()));}
 @Test void refreshDelegatesAndRedirects()throws Exception{checkout.order=order;mvc.perform(post("/checkout/R1/refresh")).andExpect(redirectedUrl("/checkout/R1"));assertEquals(1,checkout.refreshes);}
 @Test void serviceFailureRedirectsSafely()throws Exception{checkout.failure=true;mvc.perform(get("/checkout/missing")).andExpect(redirectedUrl("/checkout")).andExpect(flash().attribute("error","Không tìm thấy hoặc không thể tải đơn thuê."));}
 @Test void paymentDelegatesAndPreservesOrderData()throws Exception{checkout.order=order;BigDecimal subtotal=order.getSubtotal(),discount=order.getDiscount(),total=order.getTotal(),unitPrice=order.getDetails().getFirst().getUnitPrice();Object state=order.getCurrentState();int quantity=order.getDetails().getFirst().getQuantity();mvc.perform(post("/checkout/R1/pay")).andExpect(redirectedUrl("/checkout/R1")).andExpect(flash().attribute("success","Đã xác nhận thanh toán."));assertEquals(1,checkout.payments);assertEquals(PaymentStatus.PAID,order.getPaymentStatus());assertEquals(state,order.getCurrentState());assertEquals(subtotal,order.getSubtotal());assertEquals(discount,order.getDiscount());assertEquals(total,order.getTotal());assertEquals(unitPrice,order.getDetails().getFirst().getUnitPrice());assertEquals(quantity,order.getDetails().getFirst().getQuantity());}
 @Test void paidPaymentIsRejectedSafely()throws Exception{order.setPaymentStatus(PaymentStatus.PAID);checkout.order=order;mvc.perform(post("/checkout/R1/pay")).andExpect(redirectedUrl("/checkout/R1")).andExpect(flash().attribute("error","Không thể xác nhận thanh toán."));assertEquals(1,checkout.payments);assertEquals(PaymentStatus.PAID,order.getPaymentStatus());}
 @Test void paymentTemplateSeparatesCustomerAndAdminActions()throws Exception{String template=new String(getClass().getResourceAsStream("/templates/checkout/detail.html").readAllBytes());assertEquals(true,template.contains("session.authenticatedRole?.name() == 'CUSTOMER'")&&template.contains("/payment-method|}")&&template.contains("/report-transfer|}"));assertEquals(true,template.contains("session.authenticatedRole?.name() == 'ADMIN'")&&template.contains("/pay|}")&&template.contains("/payment-review|}")&&template.contains("/payment-reject|}"));assertEquals(true,template.contains("name=\"_csrf\"")&&template.contains("fragments/status-badges :: payment(${order.paymentStatus})")&&template.contains("checkout-transfer-qr"));}
 @Test void detailTemplateLinksBackToTheCurrentRental()throws Exception{String template=new String(getClass().getResourceAsStream("/templates/checkout/detail.html").readAllBytes());assertEquals(true,template.contains("@{/rentals/{id}(id=${order.id})}"));}
 @Test void checkoutAndSafePagesUseVietnameseCampingPresentation()throws Exception{String lookup=new String(getClass().getResourceAsStream("/templates/checkout/lookup.html").readAllBytes());String detail=new String(getClass().getResourceAsStream("/templates/checkout/detail.html").readAllBytes());String paymentScript=new String(getClass().getResourceAsStream("/static/js/checkout.js").readAllBytes());String error=new String(getClass().getResourceAsStream("/templates/error.html").readAllBytes());String notFound=new String(getClass().getResourceAsStream("/templates/error/404.html").readAllBytes());assertEquals(true,lookup.contains("Tra cứu đơn thuê")&&lookup.contains("customerNames[rental.customerId]")&&lookup.contains("@presentationLabels.rentalId"));assertEquals(true,detail.contains("Tóm tắt giá thuê")&&detail.contains("@presentationLabels.money")&&detail.contains("data-payment-confirmation"));assertEquals(true,paymentScript.contains("window.confirm")&&paymentScript.contains("button.disabled = true"));assertEquals(true,error.contains("Không thể hoàn tất yêu cầu")&&!error.contains("Exception"));assertEquals(true,notFound.contains("Không tìm thấy đơn thuê"));}
 private static RentalOrder order(){RentalDetail d=new RentalDetail();d.setEquipmentId("EQ1");d.setQuantity(2);d.setUnitPrice(new BigDecimal("100.00"));RentalOrder o=new RentalOrder();o.setId("R1");o.setCustomerId("C1");o.setRentalDate(LocalDate.of(2026,1,1));o.setExpectedReturnDate(LocalDate.of(2026,1,6));o.setDetails(List.of(d));o.setCurrentState(new RentedState());o.setPaymentStatus(PaymentStatus.UNPAID);o.setSubtotal(new BigDecimal("1000.00"));o.setDiscount(new BigDecimal("100.00"));o.setTotal(new BigDecimal("900.00"));return o;}
 private static MockHttpSession adminSession(){MockHttpSession session=new MockHttpSession();session.setAttribute(WebLoginController.AUTHENTICATED_USER_ATTRIBUTE,"admin");session.setAttribute(WebLoginController.AUTHENTICATED_ROLE_ATTRIBUTE,UserRole.ADMIN);return session;}
 private static MockHttpSession customerSession(){MockHttpSession session=new MockHttpSession();session.setAttribute(WebLoginController.AUTHENTICATED_USER_ATTRIBUTE,"customer");session.setAttribute(WebLoginController.AUTHENTICATED_ROLE_ATTRIBUTE,UserRole.CUSTOMER);session.setAttribute(WebLoginController.AUTHENTICATED_CUSTOMER_ATTRIBUTE,"C1");return session;}
 private static MockHttpSession otherCustomerSession(){MockHttpSession session=customerSession();session.setAttribute(WebLoginController.AUTHENTICATED_CUSTOMER_ATTRIBUTE,"C2");return session;}
 private static class StubCheckout extends PersistedCheckoutService { RentalOrder order; boolean failure; int loads,refreshes,payments,selections,reports; StubCheckout(){super(new RentalOrderRepository(){public void insert(RentalOrder o){}public java.util.Optional<RentalOrder> findById(String i){return java.util.Optional.empty();}public java.util.List<RentalOrder> findAll(){return List.of();}public void update(RentalOrder o){}},new CheckoutService(new RentalPricingAdapter(new PricingService())));} public RentalOrder load(String id)throws SQLException{loads++;if(failure)throw new SQLException("internal");return order;} public RentalOrder refreshPricing(String id){refreshes++;return order;} public RentalOrder confirmPayment(String id){payments++;if(order.getPaymentStatus()==PaymentStatus.PAID)throw new IllegalStateException("already paid");order.setPaymentStatus(PaymentStatus.PAID);return order;} public RentalOrder selectPaymentMethod(String id,PaymentMethod method){selections++;order.setPaymentMethod(method);order.setPaymentStatus(PaymentStatus.UNPAID);return order;} public RentalOrder reportTransfer(String id){reports++;order.setPaymentStatus(PaymentStatus.TRANSFER_REPORTED);return order;} public RentalOrder requestReview(String id){order.setPaymentStatus(PaymentStatus.REVIEW_REQUIRED);return order;} public RentalOrder rejectTransfer(String id){order.setPaymentStatus(PaymentStatus.REJECTED);return order;} }
}
